import{_ as r,a0 as i,w as a,s as n,I as o,x as e,a1 as p,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"对 DBA 最重要的 PostgreSQL 10 新亮点 | LCTT x X-CMD","titleTemplate":false,"description":"对 DBA 最重要的 PostgreSQL 10 新亮点 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"对 DBA 最重要的 PostgreSQL 10 新亮点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"对 DBA 最重要的 PostgreSQL 10 新亮点 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171013 Best of PostgreSQL 10 for the DBA","title":"对 DBA 最重要的 PostgreSQL 10 新亮点","tag":"201711","desc":""},"relativePath":"201711/20171013 Best of PostgreSQL 10 for the DBA.md","filePath":"[post].md"}'),g={name:"201711/20171013 Best of PostgreSQL 10 for the DBA.md"};function f(u,t,m,w,b,B){const s=i("Link");return a(),n("div",null,[t[26]||(t[26]=o("h1",{id:"对-dba-最重要的-postgresql-10-新亮点",tabindex:"-1"},[e("对 DBA 最重要的 PostgreSQL 10 新亮点 "),o("a",{class:"header-anchor",href:"#对-dba-最重要的-postgresql-10-新亮点","aria-label":"Permalink to “对 DBA 最重要的 PostgreSQL 10 新亮点”"},"​")],-1)),o("p",null,[t[6]||(t[6]=e("前段时间新的重大版本的 PostgreSQL 10 发布了！ 强烈建议阅读",-1)),p(s,{href:"https://www.postgresql.org/about/news/1786/"},{default:l(()=>[...t[0]||(t[0]=[e("公告",-1)])]),_:1}),t[7]||(t[7]=e("、",-1)),p(s,{href:"https://www.postgresql.org/docs/current/static/release-10.html"},{default:l(()=>[...t[1]||(t[1]=[e("发布说明",-1)])]),_:1}),t[8]||(t[8]=e("和“",-1)),p(s,{href:"https://wiki.postgresql.org/wiki/New_in_postgres_10"},{default:l(()=>[...t[2]||(t[2]=[e("新功能",-1)])]),_:1}),t[9]||(t[9]=e("”概述可以在",-1)),p(s,{href:"https://www.postgresql.org/about/news/1786/"},{default:l(()=>[...t[3]||(t[3]=[e("这里",-1)])]),_:1}),t[10]||(t[10]=e("、",-1)),p(s,{href:"https://www.postgresql.org/docs/current/static/release-10.html"},{default:l(()=>[...t[4]||(t[4]=[e("这里",-1)])]),_:1}),t[11]||(t[11]=e("和",-1)),p(s,{href:"https://wiki.postgresql.org/wiki/New_in_postgres_10"},{default:l(()=>[...t[5]||(t[5]=[e("这里",-1)])]),_:1}),t[12]||(t[12]=e("。像往常一样，已经有相当多的博客覆盖了所有新的东西，但我猜每个人都有自己认为重要的角度，所以与 9.6 版一样我再次在这里列出我印象中最有趣/相关的功能。",-1))]),t[27]||(t[27]=d(`<p>与往常一样，升级或初始化一个新集群的用户将获得更好的性能（例如，更好的并行索引扫描、合并 join 和不相关的子查询，更快的聚合、远程服务器上更加智能的 join 和聚合），这些都开箱即用，但本文中我想讲一些不能开箱即用，实际上你需要采取一些步骤才能从中获益的内容。下面重点展示的功能是从 DBA 的角度来汇编的，很快也有一篇文章从开发者的角度讲述更改。</p><h3 id="升级注意事项" tabindex="-1">升级注意事项 <a class="header-anchor" href="#升级注意事项" aria-label="Permalink to “升级注意事项”">​</a></h3><p>首先有些从现有设置升级的提示 - 有一些小的事情会导致从 9.6 或更旧的版本迁移时引起问题，所以在真正的升级之前，一定要在单独的副本上测试升级，并遍历发行说明中所有可能的问题。最值得注意的缺陷是：</p><ul><li><p>所有包含 “xlog” 的函数都被重命名为使用 “wal” 而不是 “xlog”。</p><p>后一个命名可能与正常的服务器日志混淆，因此这是一个“以防万一”的更改。如果使用任何第三方备份/复制/HA 工具，请检查它们是否为最新版本。</p></li><li><p>存放服务器日志（错误消息/警告等）的 pg_log 文件夹已重命名为 “log”。</p><p>确保验证你的日志解析或 grep 脚本（如果有）可以工作。</p></li><li><p>默认情况下，查询将最多使用 2 个后台进程。</p><p>如果在 CPU 数量较少的机器上在 <code>postgresql.conf</code> 设置中使用默认值 <code>10</code>，则可能会看到资源使用率峰值，因为默认情况下并行处理已启用 - 这是一件好事，因为它应该意味着更快的查询。如果需要旧的行为，请将 <code>max_parallel_workers_per_gather</code> 设置为 <code>0</code>。</p></li><li><p>默认情况下，本地主机的复制连接已启用。</p><p>为了简化测试等工作，本地主机和本地 Unix 套接字复制连接现在在 <code>pg_hba.conf</code> 中以“<ruby>信任<rt>trust</rt></ruby>”模式启用（无密码）！因此，如果其他非 DBA 用户也可以访问真实的生产计算机，请确保更改配置。</p></li></ul><h3 id="从-dba-的角度来看我的最爱" tabindex="-1">从 DBA 的角度来看我的最爱 <a class="header-anchor" href="#从-dba-的角度来看我的最爱" aria-label="Permalink to “从 DBA 的角度来看我的最爱”">​</a></h3><ul><li><p>逻辑复制</p><p>这个期待已久的功能在你只想要复制一张单独的表、部分表或者所有表时只需要简单的设置而性能损失最小，这也意味着之后主要版本可以零停机升级！历史上（需要 Postgres 9.4+），这可以通过使用第三方扩展或缓慢的基于触发器的解决方案来实现。对我而言这是 10 最好的功能。</p></li><li><p>声明分区</p><p>以前管理分区的方法通过继承并创建触发器来把插入操作重新路由到正确的表中，这一点很烦人，更不用说性能的影响了。目前支持的是 “range” 和 “list” 分区方案。如果有人在某些数据库引擎中缺少 “哈希” 分区，则可以使用带表达式的 “list” 分区来实现相同的功能。</p></li><li><p>可用的哈希索引</p><p>哈希索引现在是 WAL 记录的，因此是崩溃安全的，并获得了一些性能改进，对于简单的搜索，它们比在更大的数据上的标准 B 树索引快。也支持更大的索引大小。</p></li><li><p>跨列优化器统计</p><p>这样的统计数据需要在一组表的列上手动创建，以指出这些值实际上是以某种方式相互依赖的。这将能够应对计划器认为返回的数据很少（概率的乘积通常会产生非常小的数字）从而导致在大量数据下性能不好的的慢查询问题（例如选择“嵌套循环” join）。</p></li><li><p>副本上的并行快照</p><p>现在可以在 pg_dump 中使用多个进程（<code>-jobs</code> 标志）来极大地加快备用服务器上的备份。</p></li><li><p>更好地调整并行处理 worker 的行为</p><p>参考 <code>max_parallel_workers</code> 和 <code>min_parallel_table_scan_size</code>/<code>min_parallel_index_scan_size</code> 参数。我建议增加一点后两者的默认值（8MB、512KB）。</p></li><li><p>新的内置监控角色，便于工具使用</p><p>新的角色 <code>pg_monitor</code>、<code>pg_read_all_settings</code>、<code>pg_read_all_stats</code> 和 <code>pg_stat_scan_tables</code> 能更容易进行各种监控任务 - 以前必须使用超级用户帐户或一些 SECURITY DEFINER 包装函数。</p></li><li><p>用于更安全的副本生成的临时 (每个会话) 复制槽</p></li><li><p>用于检查 B 树索引的有效性的一个新的 Contrib 扩展</p><p>这两个智能检查发现结构不一致和页面级校验未覆盖的内容。希望不久的将来能更加深入。</p></li><li><p>Psql 查询工具现在支持基本分支（<code>if</code>/<code>elif</code>/<code>else</code>）</p><p>例如下面的将启用具有特定版本分支（对 pg_stat* 视图等有不同列名）的单个维护/监视脚本，而不是许多版本特定的脚本。</p></li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT :VERSION_NAME = &#39;10.0&#39; AS is_v10 \\gset </span></span>
<span class="line"><span>\\if :is_v10</span></span>
<span class="line"><span>    SELECT &#39;yippee&#39; AS msg;</span></span>
<span class="line"><span>\\else</span></span>
<span class="line"><span>    SELECT &#39;time to upgrade!&#39; AS msg;</span></span>
<span class="line"><span>\\endif</span></span></code></pre></div><p>这次就这样了！当然有很多其他的东西没有列出，所以对于专职 DBA，我一定会建议你更全面地看发布记录。非常感谢那 300 多为这个版本做出贡献的人！</p><hr>`,9)),o("p",null,[t[14]||(t[14]=e("via: ",-1)),p(s,{href:"http://www.cybertec.at/best-of-postgresql-10-for-the-dba/"},{default:l(()=>[...t[13]||(t[13]=[e("http://www.cybertec.at/best-of-postgresql-10-for-the-dba/",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=e("作者：",-1)),p(s,{href:"http://www.cybertec.at/author/kaarel-moppel/"},{default:l(()=>[...t[15]||(t[15]=[e("Kaarel Moppel",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),p(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[16]||(t[16]=[e("geekpi",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),p(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[23]||(t[23]=e("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创编译，",-1)),p(s,{href:"https://linux.cn/"},{default:l(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const L=r(g,[["render",f]]);export{A as __pageData,L as default};
